__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),e.googleSignIn=async function(s){if(!o.supabase)return(0,t.t)('\u5c1a\u672a\u8a2d\u5b9a Supabase\u3002');const u={redirectTo:`${window.location.origin}/settings`},{error:p}='link'===s?await o.supabase.auth.linkIdentity({provider:'google',options:u}):await o.supabase.auth.signInWithOAuth({provider:'google',options:u});return p?(0,n.describeAuthError)(p.message):null},e.appleAvailable=async function(){return!1},e.appleSignIn=async function(n){return(0,t.t)('\u53ea\u6709 iPhone \u7684 App \u80fd\u7528 Apple \u767b\u5165\u3002')};var n=r(d[0]),t=r(d[1]),o=r(d[2])},1032,[1031,781,802]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"TERMS_INTRO_EN",{enumerable:!0,get:function(){return o}}),Object.defineProperty(e,"TERMS_EN",{enumerable:!0,get:function(){return s}});var t=r(d[0]);const o='Flyawait (the "Service") is a flight price tracking service, as a website and an app, built and run by an individual. By starting to use the Service, you agree to these terms and the Privacy Policy. This English version is a translation; where it differs from the Chinese, the Chinese prevails.',s=[{title:'In short',blocks:[{items:["The Service is free. We search flights, track prices and alert you when they change; we don't sell flights or travel products, and we don't handle payments.",'Prices and flight information come from third parties and may be late or wrong, and alerts may arrive late or not at all. Before you book, go by what the airline or booking site shows.',"Use it fairly: don't run bulk searches with programs, and don't try to get around the limits."]}]},{title:'1. What the Service does',blocks:[{text:'The Service offers:'},{items:[['Flight search and tracking','Search fares for a route and dates, and track how they change (up to 3 tracked trips per person at a time).'],['Alerts','Push notifications when a price rises or drops, or falls below a target you set (at most 2 a day per tracked trip).'],['Explore','Cheap flights to places near and far from Taipei, Taichung and Kaohsiung.'],['Flight status and pickup sharing',"Look up a flight's departure and arrival times, gate and position by its flight number, and share a link to it."]]},{text:'Tracked prices update about every 6 to 24 hours and Explore about every 6 days, so what you see may not be the price right now. We keep improving the features; bigger changes are explained in the app or on the website.'}]},{title:'2. Your account',blocks:[{items:['You can start anonymously without an email, or link your Google account to get your tracked trips back on a new phone or another device.',"An anonymous account lives only on your device: after you change phones, clear your browser's data or use private browsing, your tracked trips can't be recovered. An anonymous account not opened in the app or on the website for 180 days in a row is deleted automatically.",'Your account is for you alone; keep the devices you sign in on safe.','You can delete your account at any time in Settings \u2192 Account, and your tracked trips and alerts go with it (data in backups is gone within 30 days at the latest; see the Privacy Policy).',"The Service isn't meant for children under 13. Minors should use it with the consent of a parent or guardian."]}]},{title:'3. Prices, flight information and alerts',blocks:[{items:[['Fares','These come from publicly available third-party information (currently Google Flights search results) and are the prices when we checked. The actual price can differ with fare changes, taxes, baggage, seats or payment method; go by what the airline or booking site shows at checkout. "Dropped" and "below target" are judged by the prices we found.'],['Flight status',"Data comes from airports and civil aviation authorities, Taiwan's Ministry of Transportation and Communications (TDX), the Airport Authority Hong Kong, and adsb.lol's volunteer receivers (ODbL). Some times (such as arrival times without airport data) are estimated from the departure time and flight time and may differ from what happens. Flight status is for reference only and must not be used for safety, emergency or legal decisions; for pickups and connections, go by what airlines and airports announce."],['Alerts','Push notifications may be late, repeated or not delivered, for example if you turned notifications off, your browser changed its push subscription, your phone is saving power, or the push service fails. Check important fares yourself instead of relying only on alerts.'],'Tracked trips whose departure date has passed are paused automatically.',"If an account hasn't opened the app or website for 30 days in a row and has no device with notifications on, its tracked trips stop checking prices; they resume automatically the next time it's opened.",'Each trip can be tracked only once.']}]},{title:'4. Third-party websites',blocks:[{items:["The Service links to third-party websites, such as airline, booking, hotel and travel product sites. We don't run these sites; orders, payments, refunds and personal data there are subject to their own terms and privacy policies, so please contact them with any questions.","We don't guarantee third-party sites' products, prices or content. Some businesses may pay us when you go to them or buy through a link."]}]},{title:'5. Fair use',blocks:[{text:"So that everyone can use the Service, please don't:"},{numbered:!0,items:["run bulk searches or scrape the Service's data with programs, scripts or bots;",'try to get around the usage limits or bot protection, or create accounts in bulk;',"interfere with or attack the Service's systems, or try to access other people's data;","resell the Service's data or use it for other commercial purposes;","use the Service for anything illegal or that infringes others' rights."]},{text:"So that everyone can use it smoothly, the Service controls the overall number and pace of lookups, so results may take longer at busy times; it also has limits against abuse (such as how many different flight numbers you can look up in flight status per hour), which may change with system conditions. If you break these terms, we may limit or stop your use of the Service and, if necessary, delete your account; where circumstances allow, we'll tell you first."}]},{title:'6. Pickup share links',blocks:[{text:"A pickup share link lets people without an account see one flight's status. Anyone who has the link can open it, and a link can't be revoked on its own, so check who you share it with."}]},{title:'7. Feedback',blocks:[{text:"What you send us through Feedback (and the email you choose to leave) is used to improve the Service and to reply to you. We may adopt your suggestions without owing you anything for it, and we won't reveal who you are."}]},{title:'8. Intellectual property',blocks:[{items:["The Service's code, design, text and icons belong to its operator.","Airline names and codes belong to their airlines; the Service uses them only to identify flights. The airline marks on screen are the Service's own designs, not the airlines' trademarks or logos.","Third-party data is used under its licenses and credited: Taiwan's Open Government Data License (MOTC TDX, airports and civil aviation authorities), the Hong Kong government's DATA.GOV.HK terms, ODbL (adsb.lol), Natural Earth (public domain) and others."]}]},{title:'9. Disclaimer and limitation of liability',blocks:[{items:["The Service is provided as is. We don't guarantee that it will be uninterrupted or error-free, that prices are correct, or that alerts will be delivered.",'Except where we act intentionally or with gross negligence, we are not liable for losses from using or being unable to use the Service, or from relying on its prices, alerts or flight information (such as a missed deal, a higher fare or a delayed trip).',"The Service is currently free. If we introduce paid features, we'll explain the price and conditions separately and ask for your agreement."]}]},{title:'10. Changes, suspension and termination',blocks:[{items:["We may suspend or stop some or all features for maintenance, changes in data sources, system load or other reasons. Before stopping the whole Service, we'll try to announce it in advance in the app and on the website.",'You can stop using it at any time, and delete your account in Settings \u2192 Account.']}]},{title:'11. Changes to these terms',blocks:[{text:"We may change these terms. For major changes we'll let you know in the app and on the website; continuing to use the Service after a change means you accept the new terms. If you don't agree, please stop using it; you can also delete your account. The version number is shown at the top of this page."}]},{title:'12. Governing law and jurisdiction',blocks:[{text:'These terms are governed by the laws of the Republic of China (Taiwan). The Taiwan Taipei District Court is the court of first instance for disputes arising from these terms, except where the law requires otherwise (for example the Consumer Protection Act, or the Code of Civil Procedure on small claims).'}]},{title:'13. Contact us',blocks:[{text:`For questions or suggestions, use Feedback in the app, or email ${t.CONTACT_EMAIL}.`}]}]},1033,[910]);
